def mirror_paste(grid, width):
    """Each non-background cell (background=most common color) at column j of an input of height H paints cells at columns mirrored about the center of a width-wide output; rows are reversed vertically."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    H = len(grid)
    half = width // 2
    A = [[bg] * width for _ in range(H)]
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v != bg:
                A[H - 1 - i][half - 1 - j] = v
                A[H - 1 - i][half + j] = v
    return A

