def vtile_mirror(grid, n):
    """The grid followed by its vertical mirror and itself again, n height-multiples total, alternating [A, flip(A)]."""
    out = []
    for k in range(n):
        out += grid if k % 2 == 0 else grid[::-1]
    return out

